referenceSolutions.javascript:
export function canConstruct(note        , magazine        )          {
  const counts = new Map                (); for (const c of magazine) counts.set(c, (counts.get(c) ?? 0) + 1); for (const c of note) { const available = counts.get(c) ?? 0; if (available === 0) return false; counts.set(c, available - 1); } return true;
}

referenceSolutions.typescript:
export function canConstruct(note: string, magazine: string): boolean {
  const counts = new Map<string, number>(); for (const c of magazine) counts.set(c, (counts.get(c) ?? 0) + 1); for (const c of note) { const available = counts.get(c) ?? 0; if (available === 0) return false; counts.set(c, available - 1); } return true;
}
